const input = $json.body ?? $json;

const name = input.name;
const phone = input.phone ? String(input.phone) : '';
const email = input.email ? String(input.email) : '';
const enquiry = input.enquiry_text || input.enquiry || '';

const nameMissing = !name || name.toString().trim() === '';
const phoneDigits = phone.replace(/\D/g, '');
const phoneValid = /^[6-9]\d{9}$/.test(phoneDigits);

const errors = [];
if (nameMissing) errors.push('Name is required.');
if (phone === '') errors.push('Phone number is required.');
else if (!phoneValid) errors.push('Phone number must be a valid 10-digit Indian mobile number.');

return {
  json: {
    name: name ? name.toString().trim() : '',
    phone,
    email,
    enquiry_text: enquiry,
    valid: errors.length === 0,
    error_message: errors.join(' ')
  }
};

