const raw = String(
  $json.output?.text ??
  $json.message?.content ??
  $json.response?.content ??
  $json.content ??
  $json.output ??
  $json.text ??
  ''
);

const original = $('Code in JavaScript').first().json;

const fallback = {
  category: 'other',
  urgency: 'low',
  summary: 'Could not classify: ' + raw.slice(0, 120),
  parse_success: false
};

try {
  let text = raw.replace(/```(?:json)?\s*/gi, '').replace(/```/g, '');
  const start = text.indexOf('{');
  const end = text.lastIndexOf('}');
  if (start === -1 || end === -1 || end < start) {
    return { json: { ...original, ...fallback, route: 'manual', ai_raw: text.slice(0, 500) } };
  }
  const parsed = JSON.parse(text.slice(start, end + 1));
  const category = ['appointment', 'billing', 'medical_query', 'complaint', 'other']
    .includes(String(parsed.category || '').toLowerCase())
    ? String(parsed.category).toLowerCase()
    : 'other';
  const urgency = ['high', 'medium', 'low']
    .includes(String(parsed.urgency || '').toLowerCase())
    ? String(parsed.urgency).toLowerCase()
    : 'low';
  return {
    json: {
      ...original,
      category,
      urgency,
      summary: String(parsed.summary || '').trim() || fallback.summary,
      parse_success: true,
      route: ['appointment', 'billing'].includes(category) ? 'auto' : 'manual'
    }
  };
} catch (e) {
  return { json: { ...original, ...fallback, route: 'manual', parse_error: e.message } };
}

