const rows = $('Read Clinic Info').all().map(r => r.json);
const facts = rows
  .map(r => `- ${r.key ?? r.field ?? ''}: ${r.value ?? r.detail ?? ''}`)
  .filter(line => line.trim().length > 2)
  .join('\n') || 'CLINIC INFO UNAVAILABLE';
const orig = $('If route auto').first().json;
return { json: { ...orig, clinic_info: facts } };

